def _norm(text):
    return ' '.join((text or '').split()).lower()


def mark_earlier_letters(apps, schema_editor):
    """Листи агента, надіслані до цієї версії, — теж «🤖 агент» у пошті: запланований лист — за темою, адресатом і
    часом відправки; чернетка, яку надіслали ви, — за початком тексту агента в надісланому листі (до 30 днів)."""
    AgentRun = apps.get_model('agent', 'AgentRun')
    AgentLetter = apps.get_model('agent', 'AgentLetter')
    AgentProposal = apps.get_model('agent', 'AgentProposal')
    ScheduledEmail = apps.get_model('email_assistant', 'ScheduledEmail')
    EmailMessage = apps.get_model('email_assistant', 'EmailMessage')

    def save(em, **kw):
        if not AgentLetter.objects.filter(account_id=em.account_id, message_id=em.message_id).exists():
            AgentLetter.objects.create(account_id=em.account_id, message_id=em.message_id, **kw)

    def sent_copy(s):
        if s is None or s.status != 'sent' or not s.sent_at:
            return None
        to = {a.lower() for a in (s.to_emails or [])}
        qs = (EmailMessage.objects.filter(account_id=s.account_id, subject=s.subject,
                                          sent_at__gte=s.sent_at - datetime.timedelta(minutes=15),
                                          sent_at__lte=s.sent_at + datetime.timedelta(hours=2))
              .exclude(message_id='').order_by('sent_at'))
        for em in qs[:5]:
            if to & {a.lower() for a in (em.to_emails or [])}:
                return em
        return None

    for run in AgentRun.objects.filter(status='scheduled', scheduled__isnull=False):
        em = sent_copy(ScheduledEmail.objects.filter(pk=run.scheduled_id).first())
        if em is not None:
            save(em, run_id=run.pk, how='sent')

    for run in AgentRun.objects.filter(status='drafted', outcome__in=('sent_same', 'sent_edited')):
        head = _norm(run.reply)[:120]
        if len(head) < 30:
            continue
        rule = run.rule
        since = run.finished_at or run.created_at
        qs = (EmailMessage.objects.filter(account_id=rule.account_id, folder='sent', sent_at__gte=since,
                                          sent_at__lte=since + datetime.timedelta(days=30))
              .exclude(message_id='').order_by('sent_at'))
        for em in qs[:300]:
            if head in _norm(em.body_text):
                save(em, run_id=run.pk, how='draft' if run.outcome == 'sent_same' else 'edited')
                break

    prefix = '/admin/email_assistant/scheduledemail/'
    for p in AgentProposal.objects.filter(kind='mail', result_url__startswith=prefix):
        pk = p.result_url[len(prefix):].split('/')[0]
        if pk.isdigit():
            em = sent_copy(ScheduledEmail.objects.filter(pk=int(pk)).first())
            if em is not None:
                save(em, task_id=p.task_id, how='sent')


